module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        reset;
    reg        slowena;
    wire [3:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .slowena(slowena),
        .q(q)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    // 3. Stimulus & self-checking
    integer errors = 0;
    reg [3:0] expected_q;

    // Task to check output against expected value using case inequality (`!==`)
    task check_output(input [3:0] exp);
        begin
            #1; // Small delay to allow clock-edge propagation
            if (q !== exp) begin
                $display("Time %0t: Mismatch! q = %b (expected %b), slowena = %b, reset = %b", 
                         $time, q, exp, slowena, reset);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        reset = 0;
        slowena = 0;
        expected_q = 4'd0;

        // Test 1: Reset behavior
        @(posedge clk);
        reset = 1;
        slowena = 1;
        expected_q = 4'd0;
        check_output(expected_q);

        // Test 2: Release reset, slowena low (counter should hold)
        @(posedge clk);
        reset = 0;
        slowena = 0;
        expected_q = 4'd0;
        check_output(expected_q);

        @(posedge clk);
        check_output(expected_q); // should still be 0

        // Test 3: Enable counting up to 9 and wrap around to 0
        slowena = 1;

        // Count from 0 to 9
        repeat (9) begin
            @(posedge clk);
            if (expected_q == 4'd9)
                expected_q = 4'd0;
            else
                expected_q = expected_q + 4'd1;
            check_output(expected_q);
        end

        // Test 4: Wrap-around verification (from 9 to 0)
        @(posedge clk);
        expected_q = 4'd0;
        check_output(expected_q);

        // Test 5: Intermittent slowena pausing
        @(posedge clk);
        slowena = 0;
        expected_q = 4'd0; // holds
        check_output(expected_q);

        @(posedge clk);
        slowena = 1;
        expected_q = 4'd1; // increments
        check_output(expected_q);

        // Final Result Display
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
